package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"time"
)

// profiles.json is generated by `fakeentsoe calibrate` from real data in ClickHouse. It holds per-zone
// aggregates only (daily shapes, spreads, structure), no raw market data.
//
//go:embed profiles.json
var embeddedProfiles []byte

// profileSet describes, per bidding zone EIC code, what the real platform publishes and how the
// values behave. A zone or dataset without a profile answers "no data", as the real API does.
type profileSet struct {
	CalibratedFrom map[string]string      `json:"calibrated_from"`
	Zones          map[string]zoneProfile `json:"zones"`
}

type zoneProfile struct {
	Price      *priceProfile `json:"price,omitempty"`
	Load       *loadProfile  `json:"load,omitempty"`
	Generation *genProfile   `json:"generation,omitempty"`
}

// curve is a daily shape: the mean per hour of the day in Europe/Amsterdam time, the spread of
// whole days around it and the spread of single slots around the day. Jitter is the share of the
// slot spread that changes from one slot to the next; the rest drifts over hours. Prices are in
// EUR/MWh, quantities in MW.
type curve struct {
	Hourly [24]float64 `json:"hourly"`
	DaySD  float64     `json:"day_sd"`
	SlotSD float64     `json:"slot_sd"`
	Jitter float64     `json:"jitter"`
	Min    float64     `json:"min"`
	Max    float64     `json:"max"`
}

type priceProfile struct {
	ResolutionMin int `json:"resolution_min"`
	curve
	Sequences []priceSequence `json:"sequences"`
}

// priceSequence is one time series per delivery day. Several auctions for one zone come as
// several sequences; the first one follows the curve, the others differ from it by Offset ± OffsetSD.
type priceSequence struct {
	Position int `json:"position"` // classificationSequence position; 0 omits the element
	// Decimals of the published amounts; 6 means float32 artefacts such as "173.869995".
	Decimals int `json:"decimals"`
	// Hours of the delivery day covered, [FirstHour, LastHour), in Europe/Amsterdam time.
	FirstHour int     `json:"first_hour"`
	LastHour  int     `json:"last_hour"`
	Offset    float64 `json:"offset"`
	OffsetSD  float64 `json:"offset_sd"`
}

type loadProfile struct {
	ResolutionMin int     `json:"resolution_min"`
	Decimals      int     `json:"decimals"`
	LagMin        int     `json:"lag_min"`      // publication after the slot ends
	MissingRate   float64 `json:"missing_rate"` // share of slots never published
	Weekday       curve   `json:"weekday"`
	Weekend       curve   `json:"weekend"`
}

type genProfile struct {
	ResolutionMin int                `json:"resolution_min"`
	Decimals      int                `json:"decimals"`
	LagMin        int                `json:"lag_min"`
	Series        []genSeriesProfile `json:"series"`
}

type genSeriesProfile struct {
	PSRType   string `json:"psr_type"`
	Direction string `json:"direction"` // generation or consumption
	// Some series are only published while the unit runs (pumped storage in BE and IT).
	MissingRate float64 `json:"missing_rate"`
	curve
}

func parseProfiles(data []byte) (*profileSet, error) {
	var p profileSet
	if err := json.Unmarshal(data, &p); err != nil {
		return nil, fmt.Errorf("decode profiles: %w", err)
	}
	for zone, z := range p.Zones {
		var res []int
		if z.Price != nil {
			if len(z.Price.Sequences) == 0 {
				return nil, fmt.Errorf("zone %s: price profile without sequences", zone)
			}
			res = append(res, z.Price.ResolutionMin)
		}
		if z.Load != nil {
			res = append(res, z.Load.ResolutionMin)
		}
		if z.Generation != nil {
			res = append(res, z.Generation.ResolutionMin)
		}
		for _, r := range res {
			if r != 15 && r != 30 && r != 60 {
				return nil, fmt.Errorf("zone %s: resolution %d min is not 15, 30 or 60", zone, r)
			}
		}
	}
	return &p, nil
}

// at returns the profile value at t, interpolated linearly between hour centres so that 15-minute
// slots follow a smooth shape instead of hourly steps.
func (c curve) at(t time.Time) float64 {
	h := localHour(t) - 0.5
	if h < 0 {
		h += 24
	}
	i := int(h)
	frac := h - float64(i)
	return c.Hourly[i%24]*(1-frac) + c.Hourly[(i+1)%24]*frac
}

func (c curve) clamp(v float64) float64 {
	return math.Min(math.Max(v, c.Min), c.Max)
}
